### src/lib/json-renderer/charts/sparkline.tsx
     1	export interface SparklineProps {
     2	  data: number[];
     3	  height?: number;
     4	  width?: number;
     5	  color?: string;
     6	  trend?: 'up' | 'down' | 'stable';
     7	}
     8	
     9	export function Sparkline({
    10	  data,
    11	  height = 40,
    12	  width = 100,
    13	  color = '#6366f1',
    14	  trend,
    15	}: SparklineProps) {
    16	  const lineColor = trend === 'up' ? '#ef4444' : trend === 'down' ? '#22c55e' : color;
    17	  const values = data.length > 0 ? data : [0];
    18	  const min = Math.min(...values);
    19	  const max = Math.max(...values);
    20	  const range = max - min || 1;
    21	  const stepX = values.length > 1 ? width / (values.length - 1) : width;
    22	
    23	  const points = values
    24	    .map((value, index) => {
    25	      const x = values.length > 1 ? index * stepX : width / 2;
    26	      const y = height - ((value - min) / range) * (height - 4) - 2;
    27	      return `${x},${y}`;
    28	    })
    29	    .join(' ');
    30	
    31	  const areaPoints = `${points} ${width},${height} 0,${height}`;
    32	
    33	  return (
    34	    <svg
    35	      width={width}
    36	      height={height}
    37	      viewBox={`0 0 ${width} ${height}`}
    38	      role="img"
    39	      aria-hidden="true"
    40	      className="overflow-visible"
    41	    >
    42	      <polygon points={areaPoints} fill={lineColor} fillOpacity="0.12" />
    43	      <polyline
    44	        points={points}
    45	        fill="none"
    46	        stroke={lineColor}
    47	        strokeWidth="2"
    48	        strokeLinecap="round"
    49	        strokeLinejoin="round"
    50	      />
    51	    </svg>
    52	  );
    53	}

