    20	
    21	// Color palette for platforms
    22	const platformColors: Record<string, string> = {
    23	  reddit: '#FF4500',
    24	  github: '#333333',
    25	  trustpilot: '#00B67A',
    26	  hackernews: '#FF6600',
    27	  x: '#1DA1F2',
    28	  ios_appstore: '#007AFF',
    29	  google_play: '#34A853',
    30	  glassdoor: '#0CAA41',
    31	  g2: '#FF492C',
    32	  capterra: '#FF6B35',
    33	  gmaps: '#4285F4',
    34	};
    35	
    36	// Default colors for unknown platforms
    37	const defaultColors = [
    38	  '#6366f1',
    39	  '#8b5cf6',
    40	  '#d946ef',
    41	  '#ec4899',
    42	  '#f43f5e',
    43	  '#f97316',
    44	  '#eab308',
    45	  '#84cc16',
    46	  '#22c55e',
    47	  '#14b8a6',
    48	];
    49	
    50	function getColorForPlatform(key: string, index: number): string {
    51	  return platformColors[key.toLowerCase()] || defaultColors[index % defaultColors.length];
    52	}
    53	
    54	export function StackedAreaChart({
    55	  data,
    56	  series,
    57	  height = 180,
    58	  xLabel = '',
    59	  yLabel = '',
    60	  onSeriesClick,
    61	  onDateRangeSelect,
    62	}: StackedAreaChartProps) {
    63	  const option: EChartsOption = useMemo(() => {
    64	    const chartSeries = series.map((s, i) => ({
    65	      name: s.name,
    66	      type: 'line' as const,
    67	      stack: 'total',
    68	      areaStyle: {
    69	        opacity: 0.6,
    70	      },
    71	      emphasis: {
    72	        focus: 'series' as const,
    73	      },
    74	      smooth: true,
    75	      data: data.map((d) => d[s.key] ?? 0),
    76	      itemStyle: {
    77	        color: s.color || getColorForPlatform(s.key, i),
    78	      },
    79	      lineStyle: {
    80	        width: 1,
    81	        color: s.color || getColorForPlatform(s.key, i),
    82	      },
    83	    }));
    84	
    85	    return {
    86	      tooltip: {
    87	        trigger: 'axis',
    88	        axisPointer: {
    89	          type: 'cross',
    90	          label: {
    91	            backgroundColor: '#6a7985',
    92	          },
    93	        },
    94	      },
    95	      legend: {
    96	        type: 'scroll',
    97	        bottom: 0,
    98	        data: series.map((s) => s.name),
    99	        selectedMode: 'multiple',
   100	      },
   101	      grid: {
   102	        left: 50,
   103	        right: 20,
   104	        top: 20,
   105	        bottom: 60,
   106	        containLabel: true,
   107	      },
   108	      xAxis: {
   109	        type: 'category',
   110	        boundaryGap: false,
   111	        data: data.map((d) => d.date),
   112	        name: xLabel,
   113	        nameLocation: 'middle',
   114	        nameGap: 30,
   115	        axisLabel: {
   116	          formatter: (value: string) => {
   117	            const date = new Date(value);
   118	            return `${date.getMonth() + 1}/${date.getDate()}`;
   119	          },
   120	        },
   121	      },
   122	      yAxis: {
   123	        type: 'value',
   124	        name: yLabel,
   125	        nameLocation: 'middle',
   126	        nameGap: 40,
   127	        minInterval: 1,
   128	      },
   129	      dataZoom: [
   130	        {
   131	          type: 'inside',
   132	          start: 0,
   133	          end: 100,
   134	        },
   135	        {
   136	          type: 'slider',
   137	          show: false,
   138	        },
   139	      ],
   140	      series: chartSeries,
   141	    };
   142	  }, [data, series, xLabel, yLabel]);
   143	
   144	  // Handle data zoom for date range selection
   145	  const handleDataZoom = useCallback(
   146	    (params: { start?: number; end?: number }) => {
   147	      if (
   148	        onDateRangeSelect &&
   149	        data.length > 0 &&
   150	        params.start !== undefined &&
   151	        params.end !== undefined
   152	      ) {
   153	        const startIdx = Math.floor((params.start / 100) * data.length);
   154	        const endIdx = Math.ceil((params.end / 100) * data.length) - 1;
   155	        if (startIdx >= 0 && endIdx < data.length) {
   156	          const startDate = data[startIdx]?.date as string;
   157	          const endDate = data[endIdx]?.date as string;
   158	          if (startDate && endDate) {
   159	            onDateRangeSelect(startDate, endDate);
   160	          }
   161	        }
   162	      }
   163	    },
   164	    [data, onDateRangeSelect]
   165	  );
   166	
   167	  const { chartRef, getInstance } = useECharts({ option, onDataZoom: handleDataZoom });
   168	
   169	  // Set up legend click listener
   170	  useEffect(() => {
   171	    const chart = getInstance();
   172	    if (!chart || !onSeriesClick) return;
   173	
   174	    const handleLegendClick = (params: { selected: Record<string, boolean> }) => {
   175	      const changedSeries = Object.entries(params.selected).find(
   176	        ([, selected]) => selected === false
   177	      );
   178	      if (changedSeries) {
   179	        const seriesConfig = series.find((s) => s.name === changedSeries[0]);
   180	        if (seriesConfig) {
   181	          onSeriesClick(seriesConfig.key);
   182	        }
   183	      }
   184	    };
   185	
   186	    chart.on('legendselectchanged', handleLegendClick as () => void);
   187	
   188	    return () => {
   189	      chart.off('legendselectchanged', handleLegendClick as () => void);
   190	    };
   191	  }, [getInstance, series, onSeriesClick]);
   192	
   193	  return <div ref={chartRef} style={{ width: '100%', height }} />;
   194	}

