   275		pendingId?: string | null;
   276		resolvedId?: string | null;
   277	}> = ({ view, onAction, pendingId = null, resolvedId = null }) => {
   278		const [confirmingId, setConfirmingId] = useState<string | null>(null);
   279		const tone = view.tone ?? "default";
   280		const actions = view.actions ?? [];
   281		const blocks = view.blocks ?? EMPTY_BLOCKS;
   282		const [formValues, setFormValues] = useState<Record<string, unknown>>(() =>
   283			initialFormValues(blocks),
   284		);
   285		const pending = pendingId !== null;
   286	
   287		useEffect(() => {
   288			setFormValues(initialFormValues(blocks));
   289		}, [blocks]);
   290	
   291		if (resolvedId) {
   292			const resolved = actions.find((a) => a.id === resolvedId);
   293			return (
   294				<div
   295					className={cn(FILLED_BOX, "px-3 py-2 text-xs text-muted-foreground")}
   296				>
   297					{resolved?.resolvedLabel ?? "Done."}
   298				</div>
   299			);
   300		}
   301	
   302		const confirming = confirmingId
   303			? actions.find((a) => a.id === confirmingId)
   304			: null;
   305		const submitAction = (action: InteractionAction) => {
   306			if (!action.submitFormAs || !isToolAction(action)) {
   307				onAction(action);
   308				return;
   309			}
   310			onAction({
   311				...action,
   312				args: {
