   324				<Button
   325					type="button"
   326					size="sm"
   327					variant="destructive"
   328					disabled={pending}
   329					onClick={() => submitAction(confirming)}
   330				>
   331					{pendingId === confirming.id ? (
   332						<Spinner size="lg" className="mr-1" />
   333					) : null}
   334					Confirm
   335				</Button>
   336				<Button
   337					type="button"
   338					size="sm"
   339					variant="outline"
   340					disabled={pending}
   341					onClick={() => setConfirmingId(null)}
   342				>
   343					Cancel
   344				</Button>
   345			</div>
   346		) : (
   347			<div className="flex flex-wrap items-center gap-1.5">
   348				{actions.map((a) => {
