   350					return (
   351						<Button
   352							key={a.id}
   353							type="button"
   354							size="sm"
   355							variant={VARIANT[a.variant ?? "outline"]}
   356							disabled={pending}
   357							onClick={() =>
   358								a.confirm ? setConfirmingId(a.id) : submitAction(a)
   359							}
   360						>
   361							{pendingId === a.id ? (
   362								<Spinner size="lg" className="mr-1" />
   363							) : Icon ? (
   364								<Icon className="mr-1 h-3.5 w-3.5" />
   365							) : null}
   366							{a.label}
   367						</Button>
   368					);
   369				})}
   370			</div>
   371		);
   372	
   373		if (tone === "bare") return actionRow;
   374	
   375		const container =
   376			tone === "warning"
   377				? "rounded-lg border border-amber-500/40 bg-amber-500/10 px-3 py-2.5 text-xs"
   378				: cn(FILLED_BOX, "px-3 py-2");
   379	
   380		return (
   381			<div className={container}>
   382				{view.title ? (
   383					<div className="mb-2 flex items-center gap-1.5 font-medium">
   384						{tone === "warning" ? (
   385							<ShieldAlert className="h-3.5 w-3.5 text-amber-600 dark:text-amber-500" />
   386						) : null}
   387						<span>{view.title}</span>
   388					</div>
   389				) : null}
   390				{blocks.length > 0 ? (
   391					<div className="mb-2 space-y-2">
   392						{blocks.map((b) => (
   393							<BlockView
   394								key={blockKey(b)}
   395								block={b}
   396								onAction={onAction}
   397								onFormValuesChange={setFormValues}
   398								disabled={pending}
   399							/>
   400						))}
   401					</div>
   402				) : null}
   403				{actions.length > 0 ? actionRow : null}
   404			</div>
   405		);
   406	};

