    44	type DescriptionPart =
    45	  | { id: string; type: 'text'; value: string }
    46	  | { id: string; type: 'link'; href: string; label: string };
    47	
    48	function parseAnchoredText(input: string): DescriptionPart[] {
    49	  const parts: DescriptionPart[] = [];
    50	  const anchorRegex = /<a\b[^>]*href=['"]([^'"]+)['"][^>]*>(.*?)<\/a>/gi;
    51	  let cursor = 0;
    52	  let match: RegExpExecArray | null = anchorRegex.exec(input);
    53	
    54	  while (match !== null) {
    55	    const [fullMatch, href, label] = match;
    56	    const start = match.index;
    57	
    58	    if (start > cursor) {
    59	      parts.push({
    60	        id: `text-${cursor}-${start}`,
    61	        type: 'text',
    62	        value: input.slice(cursor, start),
    63	      });
    64	    }
    65	
    66	    parts.push({
    67	      id: `link-${start}-${start + fullMatch.length}`,
    68	      type: 'link',
    69	      href: href.trim(),
    70	      label: label.replace(/<[^>]*>/g, '').trim() || href.trim(),
    71	    });
    72	
    73	    cursor = start + fullMatch.length;
    74	    match = anchorRegex.exec(input);
    75	  }
    76	
    77	  if (cursor < input.length) {
    78	    parts.push({
    79	      id: `text-${cursor}-${input.length}`,
    80	      type: 'text',
    81	      value: input.slice(cursor),
    82	    });
    83	  }
    84	
    85	  return parts.length > 0 ? parts : [{ id: `text-0-${input.length}`, type: 'text', value: input }];
    86	}
