   127	// ============================================================
   128	// Schema Parsing Functions
   129	// ============================================================
   130	
   131	function formatLabel(name: string): string {
   132	  return name
   133	    .split('_')
   134	    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
   135	    .join(' ');
   136	}
   137	
   138	function extractLabelFromDescription(description: string | undefined, fieldName: string): string {
   139	  if (!description) return formatLabel(fieldName);
   140	  // Strip a trailing parenthetical example. The comma after "e.g." is optional:
   141	  // matching only "(e.g., …)" left "(e.g. …)" in place, and the sentence split
   142	  // below then cut at the period inside "e.g." — rendering a Gmail field as
   143	  // `Gmail label to sync (e`.
   144	  const label = description.replace(/\s*\(e\.g\.,?\s.*?\)/gis, '').trim();
   145	  // Take the first sentence, but ignore periods that are part of an
   146	  // abbreviation ("e.g.", "i.e.") or a decimal rather than a sentence end.
   147	  const firstSentence = label
   148	    .split(/(?<![A-Za-z0-9])\.(?=\s|$)|\.(?=\s+[A-Z])/)[0]
   149	    .trim()
   150	    // Stripping a trailing "(e.g. …)" leaves the sentence period dangling.
   151	    .replace(/\.$/, '');
   152	  return firstSentence || label || formatLabel(fieldName);
   153	}
   154	
   155	function formatExampleValue(example: unknown): string | undefined {
   156	  if (example === undefined || example === null) return undefined;
   157	  if (typeof example === 'string' || typeof example === 'number' || typeof example === 'boolean') {
   158	    return String(example);
   159	  }
   160	  if (Array.isArray(example)) {
   161	    const parts = example
   162	      .map((item) =>
   163	        typeof item === 'string' || typeof item === 'number' || typeof item === 'boolean'
   164	          ? String(item)
   165	          : null
   166	      )
   167	      .filter((item): item is string => item !== null);
   168	    if (parts.length > 0) return parts.join(', ');
   169	  }
   170	  try {
   171	    return JSON.stringify(example);
   172	  } catch {
   173	    return undefined;
   174	  }
   175	}
   176	
   177	function parseField(
   178	  name: string,
   179	  schema: Record<string, unknown>,
   180	  isRequired: boolean
   181	): FieldConfig | null {
   182	  // Handle Optional wrapper (TypeBox style)
   183	  const anyOf = schema.anyOf as Array<Record<string, unknown>> | undefined;
   184	  if (anyOf && anyOf.length > 0) {
   185	    const nullOption = anyOf.find((opt) => opt.type === 'null');
   186	    if (nullOption) {
   187	      const nonNullOptions = anyOf.filter((opt) => opt.type !== 'null');
   188	      if (nonNullOptions.length === 1) {
   189	        return parseField(name, nonNullOptions[0], false);
   190	      }
   191	      isRequired = false;
   192	    }
   193	  }
   194	
   195	  const config: FieldConfig = {
   196	    name,
   197	    label:
   198	      (schema.title as string | undefined) ||
   199	      extractLabelFromDescription(schema.description as string | undefined, name),
   200	    type: 'text',
   201	    required: isRequired,
   202	    description: schema.description as string | undefined,
   203	    defaultValue: schema.default,
   204	    example: schema.example,
   205	  };
   206	  const examplePlaceholder = formatExampleValue(schema.example);
   207	
   208	  // Determine field type
   209	  if (schema.type === 'string') {
   210	    config.type = schema.format === 'password' ? 'password' : 'text';
   211	    config.placeholder = examplePlaceholder || `Enter ${formatLabel(name).toLowerCase()}`;
   212	    config.validation = {
   213	      minLength: schema.minLength as number | undefined,
   214	      maxLength: schema.maxLength as number | undefined,
   215	    };
   216	  } else if (schema.type === 'number' || schema.type === 'integer') {
   217	    config.type = 'number';
   218	    config.placeholder = examplePlaceholder;
   219	    config.validation = {
   220	      min: schema.minimum as number | undefined,
   221	      max: schema.maximum as number | undefined,
   222	    };
   223	  } else if (schema.type === 'boolean') {
   224	    config.type = 'boolean';
   225	  } else if (schema.type === 'array') {
   226	    const items = schema.items as Record<string, unknown> | undefined;
   227	    if (items?.enum && Array.isArray(items.enum)) {
   228	      config.type = 'multi-select';
   229	      config.options = (items.enum as Array<string | number>).map((value) => ({
   230	        value,
   231	        label: formatLabel(String(value)),
   232	      }));
   233	    } else if (items?.anyOf || items?.oneOf) {
   234	      const unionOptions = (items.anyOf || items.oneOf) as Array<Record<string, unknown>>;
   235	      const literalValues = unionOptions
   236	        .filter((opt) => opt.const !== undefined)
   237	        .map((opt) => opt.const as string | number);
   238	      if (literalValues.length > 0) {
   239	        config.type = 'multi-select';
   240	        config.options = literalValues.map((value) => ({
   241	          value,
   242	          label: formatLabel(String(value)),
   243	        }));
   244	      } else {
   245	        config.type = 'array';
   246	        config.placeholder = examplePlaceholder ?? 'Add items...';
   247	      }
   248	    } else {
   249	      config.type = 'array';
   250	      config.placeholder = examplePlaceholder ?? 'Add items...';
   251	    }
   252	    config.validation = {
   253	      minItems: schema.minItems as number | undefined,
   254	      maxItems: schema.maxItems as number | undefined,
   255	    };
   256	  } else if (anyOf) {
   257	    // Union types -> select dropdown
   258	    const literalValues = anyOf
   259	      .filter((opt) => opt.const !== undefined)
   260	      .map((opt) => opt.const as string | number);
   261	    if (literalValues.length > 0) {
   262	      config.type = 'select';
   263	      config.options = literalValues.map((value) => ({
   264	        value,
   265	        label: formatLabel(String(value)),
   266	      }));
   267	      config.placeholder = examplePlaceholder;
   268	    }
   269	  }
   270	
   271	  // Check for enum
   272	  if (schema.enum && Array.isArray(schema.enum)) {
   273	    config.type = 'select';
   274	    config.options = (schema.enum as Array<string | number>).map((value) => ({
   275	      value,
   276	      label: formatLabel(String(value)),
   277	    }));
   278	    config.placeholder = examplePlaceholder;
   279	  }
   280	
   281	  return config;
   282	}
   283	
   284	function parseSchema(schema: Record<string, unknown> | undefined): FieldConfig[] {
   285	  if (!schema?.properties) return [];
   286	
   287	  const fields: FieldConfig[] = [];
   288	  const properties = schema.properties as Record<string, Record<string, unknown>>;
   289	  const required = (schema.required as string[]) || [];
   290	
   291	  for (const [fieldName, fieldSchema] of Object.entries(properties)) {
   292	    const field = parseField(fieldName, fieldSchema, required.includes(fieldName));
   293	    if (field) fields.push(field);
   294	  }
   295	
   296	  return fields;
   297	}
