   303	interface DynamicConnectorFormProps {
   304	  connectorType?: ConnectorType;
   305	  schema?: Record<string, unknown>;
   306	  initialValues?: Record<string, unknown>;
   307	  onValuesChange?: (values: Record<string, unknown>) => void;
   308	  /** Route description links through a containing host instead of raw anchors. */
   309	  onOpenLink?: (href: string) => void;
   310	  fieldIdPrefix?: string;
   311	  readOnly?: boolean;
   312	}
   313	
   314	const EMPTY_VALUES: Record<string, unknown> = {};
   315	
   316	export function DynamicConnectorForm({
   317	  connectorType,
   318	  schema,
   319	  initialValues = EMPTY_VALUES,
   320	  onValuesChange,
   321	  onOpenLink,
   322	  fieldIdPrefix = '',
   323	  readOnly = false,
   324	}: DynamicConnectorFormProps) {
   325	  // Parse schema to get fields
   326	  const fields = useMemo(
   327	    () => parseSchema(schema ?? connectorType?.options_schema),
   328	    [schema, connectorType]
   329	  );
   330	
   331	  // Form state
   332	  const [formValues, setFormValues] = useState<Record<string, unknown>>({});
   333	
   334	  // Initialize form values
   335	  useEffect(() => {
   336	    const newValues: Record<string, unknown> = {};
   337	    fields.forEach((field) => {
   338	      if (field.name in initialValues) {
   339	        newValues[field.name] = initialValues[field.name];
   340	      } else if (readOnly && field.example !== undefined) {
   341	        // In read-only mode, show example values
   342	        newValues[field.name] =
   343	          field.type === 'array' && Array.isArray(field.example) ? field.example : field.example;
   344	      } else if (field.defaultValue !== undefined) {
   345	        newValues[field.name] = field.defaultValue;
   346	      } else if (field.type === 'multi-select' || field.type === 'array') {
   347	        newValues[field.name] = [];
   348	      } else if (field.type === 'boolean') {
   349	        newValues[field.name] = false;
   350	      } else {
   351	        newValues[field.name] = '';
   352	      }
   353	    });
   354	    setFormValues(newValues);
   355	  }, [initialValues, fields, readOnly]);
   356	
   357	  // Notify parent of changes
   358	  const notifyChanges = useCallback(
   359	    (values: Record<string, unknown>) => {
   360	      const cleanOptions: Record<string, unknown> = {};
   361	      fields.forEach((field) => {
   362	        const value = values[field.name];
