     4	function inlineMarkdown(
     5		text: string,
     6		openLink: (href: string) => void,
     7	): ReactNode[] {
     8		const nodes: ReactNode[] = [];
     9		const pattern =
    10			/(\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)|\*\*([^*]+)\*\*|~~([^~]+)~~|`([^`]+)`|\*([^*]+)\*)/g;
    11		let cursor = 0;
    12		for (const match of text.matchAll(pattern)) {
    13			const index = match.index ?? 0;
    14			if (index > cursor) nodes.push(text.slice(cursor, index));
    15			if (match[2] && match[3] && isExternalHttpUrl(match[3])) {
    16				nodes.push(
    17					<button
    18						key={`${index}:${match[3]}`}
    19						type="button"
    20						className="inline text-primary underline"
    21						onClick={() => openLink(match[3])}
    22					>
    23						{match[2]}
    24					</button>,
    25				);
    26			} else if (match[4]) {
    27				nodes.push(<strong key={index}>{match[4]}</strong>);
    28			} else if (match[5]) {
    29				nodes.push(<del key={index}>{match[5]}</del>);
    30			} else if (match[6]) {
    31				nodes.push(
    32					<code
    33						key={index}
    34						className="rounded bg-muted px-1 py-0.5 font-mono text-[0.9em]"
    35					>
    36						{match[6]}
    37					</code>,
    38				);
    39			} else if (match[7]) {
    40				nodes.push(<em key={index}>{match[7]}</em>);
    41			} else {
    42				nodes.push(match[0]);
    43			}
    44			cursor = index + match[0].length;
    45		}
    46		if (cursor < text.length) nodes.push(text.slice(cursor));
    47		return nodes;
    48	}
