   243	function supportsMcpApps(capabilities: Record<string, unknown> | null | undefined): boolean {
   244	  const extensions = capabilities?.extensions;
   245	  if (!extensions || typeof extensions !== 'object') return false;
   246	  const uiExtension = (extensions as Record<string, unknown>)[MCP_APP_EXTENSION_ID];
   247	  if (!uiExtension || typeof uiExtension !== 'object') return false;
   248	  const mimeTypes = (uiExtension as Record<string, unknown>).mimeTypes;
   249	  return Array.isArray(mimeTypes) && mimeTypes.includes(MCP_APP_MIME_TYPE);
   250	}
