   252	function createServerForContext(
   253	  env: Env,
   254	  authCtx: SessionAuthContext,
   255	  mcpAppsSupported: boolean
   256	): Server {
   257	  const server = new Server(
   258	    { name: 'lobu-mcp', version: '0.2.0' },
   259	    {
   260	      capabilities: { tools: {}, resources: {} },
   261	      ...(authCtx.instructions && { instructions: authCtx.instructions }),
   262	    }
   263	  );
   264	
   265	  // tools/list — agent-facing surface only (memory + SDK scripting + SQL/metrics).
   266	  // Admin flat tools stay dispatchable via tools/call and REST but are omitted
   267	  // here so agents compose through query_sdk / run_sdk instead.
   268	  server.setRequestHandler(ListToolsRequestSchema, async () => {
   269	    const publicOnly = !!authCtx.organizationId && !authCtx.memberRole;
   270	    const maxAccessLevel = resolveMaxAccessLevel(authCtx.memberRole, authCtx.scopes);
   271	    const allTools = getMcpTools({
   272	      publicOnly,
   273	      maxAccessLevel,
   274	    })
   275	      .filter((t) => {
   276	        const visibility = (t._meta?.ui as { visibility?: unknown } | undefined)?.visibility;
   277	        return mcpAppsSupported || !(
   278	          Array.isArray(visibility) && visibility.length === 1 && visibility[0] === 'app'
   279	        );
   280	      })
   281	      .map((t) => {
   282	        const securitySchemes = t.securitySchemes
   283	          ? publicOnly
   284	            ? [{ type: 'noauth' as const }, ...t.securitySchemes]
   285	            : t.securitySchemes
   286	          : undefined;
   287	        const appMeta = mcpAppsSupported ? t._meta : undefined;
   288	        return {
   289	          name: t.name,
   290	          description: t.description,
   291	          inputSchema: t.inputSchema,
   292	          ...(t.annotations && { annotations: t.annotations }),
   293	          ...(t.outputSchema && { outputSchema: t.outputSchema }),
   294	          ...(securitySchemes && { securitySchemes }),
   295	          ...(appMeta || securitySchemes
   296	            ? {
   297	                _meta: {
   298	                  ...(appMeta ?? {}),
   299	                  // MCP Apps 2025-11-25 retains `_meta.securitySchemes` as the
   300	                  // compatibility mirror for hosts that predate the top-level field.
   301	                  ...(securitySchemes && { securitySchemes }),
   302	                },
   303	              }
   304	            : {}),
   305	        };
   306	      });
   307	
   308	    return { tools: allTools };
   309	  });
   310	
   311	  // resources/list — advertise the MCP App UI resources (interactive iframe
   312	  // surfaces a host renders in place of flat text; see MCP Apps).
   313	  server.setRequestHandler(ListResourcesRequestSchema, async () => ({
   314	    resources: [
   315	      ...Object.entries(MCP_APP_RESOURCES).map(([uri, meta]) => ({
   316	        uri,
   317	        name: meta.name,
   318	        description: meta.description,
   319	        mimeType: MCP_APP_MIME_TYPE,
   320	        _meta: {
   321	          ui: {
   322	            csp: meta.csp,
   323	            prefersBorder: meta.prefersBorder,
   324	          },
   325	        },
   326	      })),
   327	      ...Object.entries(MCP_SKILL_RESOURCES).map(([uri, meta]) => ({
   328	        uri,
   329	        name: meta.name,
   330	        description: meta.description,
   331	        mimeType: 'text/markdown',
   332	      })),
   333	    ],
   334	  }));
   335	
   336	  // resources/read — return the built bundle HTML for a `ui://` app resource.
   337	  server.setRequestHandler(ReadResourceRequestSchema, async (request) => {
   338	    const uri = request.params.uri;
   339	    const skill = MCP_SKILL_RESOURCES[uri];
   340	    if (skill) {
   341	      return {
   342	        contents: [{ uri, mimeType: 'text/markdown', text: skill.text }],
   343	      };
   344	    }
   345	    const app = MCP_APP_RESOURCES[uri];
   346	    if (!app) throw new Error(`Unknown resource: ${uri}`);
   347	    const html = await readMcpAppBundle(app.appDir);
   348	    if (html == null) {
   349	      throw new Error(`MCP App bundle not built for ${uri} (run owletto build:mcp-apps)`);
   350	    }
   351	    return {
   352	      contents: [
   353	        {
   354	          uri,
   355	          mimeType: MCP_APP_MIME_TYPE,
   356	          text: html,
   357	          _meta: { ui: { csp: app.csp, prefersBorder: app.prefersBorder } },
   358	        },
   359	      ],
   360	    };
   361	  });
   362	
   363	  // tools/call — access control + execution + formatting
   364	  server.setRequestHandler(CallToolRequestSchema, async (request) => {
   365	    const { name, arguments: args } = request.params;
   366	    const callAuthCtx = {
   367	      ...authCtx,
   368	      mcpAppsSupported,
   369	      mcpConversationId: hostConversationIdFromMeta(request.params._meta),
   370	      mcpAppApprovalCapability: approvalCapabilityFromMeta(request.params._meta),
   371	    };
   372	
   373	    // Regular tool execution
   374	    try {
   375	      const result = await executeTool(name, args ?? {}, env, callAuthCtx);
   376	
   377	      if (authCtx.agentId && authCtx.organizationId) {
   378	        await touchAgentLastUsed(authCtx.organizationId, authCtx.agentId);
